"use client";

import { ChevronDown } from "lucide-react";
import { useId, useState, type ReactNode } from "react";
import { cn } from "./lib/cn";
import "./shared/accordion-panel.css";

export function Collapsible({
  title,
  children,
  open,
  defaultOpen = false,
  onOpenChange,
  className,
}: {
  title: string;
  children: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}) {
  const [local, setLocal] = useState(defaultOpen);
  const shown = open ?? local;
  const panelId = useId();

  return (
    <div data-slot="collapsible" className={cn("max-w-lg rounded-overlay border border-border px-3", className)}>
      <button
        type="button"
        aria-expanded={shown}
        aria-controls={panelId}
        data-slot="accordion-trigger"
        className="flex min-h-11 w-full items-center justify-between gap-3 text-left text-sm font-medium outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
        onClick={() => {
          const next = !shown;
          if (open == null) setLocal(next);
          onOpenChange?.(next);
        }}
      >
        {title}
        <ChevronDown aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
      </button>
      <div id={panelId} data-slot="accordion-panel" data-open={shown || undefined} inert={shown ? undefined : true}>
        <div className="pb-3 text-sm leading-6 text-muted-foreground">{children}</div>
      </div>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* Shared by accordion.tsx, collapsible.tsx, expandable-card.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="accordion-panel"] {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows var(--duration-travel) var(--ease-settle);
  }
  [data-slot="accordion-panel"][data-open="true"] {
    grid-template-rows: 1fr;
  }
  [data-slot="accordion-panel"] > div {
    min-height: 0;
    overflow: hidden;
    opacity: 0;
    transform: translateY(6px);
    transition:
      opacity var(--duration-fast) var(--ease-out),
      transform var(--duration-travel) var(--ease-showcase);
  }
  [data-slot="accordion-panel"][data-open="true"] > div {
    opacity: 1;
    transform: none;
  }
  [data-slot="accordion-trigger"] svg {
    transition: transform var(--duration-travel) var(--ease-showcase);
  }
  [data-slot="accordion-trigger"][aria-expanded="true"] svg {
    transform: rotate(180deg);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="accordion-panel"] > div {
      transition:
        opacity 120ms var(--ease-out),
        transform 400ms var(--ease-showcase);
    }
    [data-slot="accordion-panel"] {
      transition: grid-template-rows 400ms var(--ease-settle);
    }
    [data-slot="accordion-trigger"] svg {
      transition-duration: 400ms;
    }
  }
}
